// Reduce the raw Notion properties object to a compact schema:
// keeps only id/name/type (+ select/multi_select options), to save tokens in the generation prompt.
return items.map(item => {
  const inputDatabase = item.json.inputDatabase;
  const simplifiedProperties = Object.fromEntries(Object.entries(inputDatabase.properties || {}).map(([key, value]) => {
    const simplifiedValue = { id: value.id, name: value.name, type: value.type };
    if (value.type === 'multi_select' || value.type === 'select') {
      simplifiedValue.options = (value.multi_select?.options || value.select?.options || []).map(option => option.name);
    }
    return [key, simplifiedValue];
  }));
  item.json.inputDatabase.properties = simplifiedProperties;
  return item;
});

