DER\\\", \\\"rich_text\\\": { \\\"contains\\\": $fromAI('keyword', 'Search keyword to match against the primary text property', 'string') } }, { \\\"property\\\": \\\"TAG_PROPERTY_PLACEHOLDER\\\", \\\"multi_select\\\": { \\\"contains\\\": $fromAI('tag', 'Tag to filter by, one of the known tag options', 'string') } } ] }, \\\"sorts\\\": [ { \\\"timestamp\\\": \\\"last_edited_time\\\", \\\"direction\\\": \\\"descending\\\" } ] } }}\"},\"id\":\"tool-1\",\"name\":\"Search Notion Database\",\"type\":\"n8n-nodes-base.httpRequestTool\",\"typeVersion\":4.4,\"position\":[960,680],\"credentials\":{\"notionApi\":{\"id\":\"\",\"name\":\"Notion account\"}}},{\"parameters\":{\"descriptionType\":\"manual\",\"toolDescription\":\"Retrieve the full block content of a specific Notion page by its page_id (obtained from Search Notion Database results).\",\"method\":\"GET\",\"url\":\"=https://api.notion.com/v1/blocks/{{ $fromAI('page_id', 'Notion page ID from a previous search result') }}/children\",\"authentication\":\"predefinedCredentialType\",\"nodeCredentialType\":\"notionApi\"},\"id\":\"tool-2\",\"name\":\"Read Notion Page Content\",\"type\":\"n8n-nodes-base.httpRequestTool\",\"typeVersion\":4.4,\"position\":[1160,680],\"credentials\":{\"notionApi\":{\"id\":\"\",\"name\":\"Notion account\"}}}],\"connections\":{\"OpenAI Chat Model\":{\"ai_languageModel\":[[{\"node\":\"AI Agent\",\"type\":\"ai_languageModel\",\"index\":0}]]},\"Simple Memory\":{\"ai_memory\":[[{\"node\":\"AI Agent\",\"type\":\"ai_memory\",\"index\":0}]]},\"Search Notion Database\":{\"ai_tool\":[[{\"node\":\"AI Agent\",\"type\":\"ai_tool\",\"index\":0}]]},\"Read Notion Page Content\":{\"ai_tool\":[[{\"node\":\"AI Agent\",\"type\":\"ai_tool\",\"index\":0}]]},\"When chat message received\":{\"main\":[[{\"node\":\"AI Agent\",\"type\":\"main\",\"index\":0}]]}}}")
  }
